import React from 'react';
import './App.css';
import LocationQuiz from './LocationQuiz'; // Import the LocationQuiz component
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';

function App() {
  const theme = createTheme({
    palette: {
      mode: 'dark', // ダークモードを有効にする
    },
  });
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <LocationQuiz />
    </ThemeProvider>
  );
}

export default App;
