import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import Paper from '@mui/material/Paper';
import Fab from '@mui/material/Fab';
import MyLocationIcon from '@mui/icons-material/MyLocation';
import Box from '@mui/material/Box';

interface UserLocation {
  latitude: number;
  longitude: number;
}

interface MapDisplayProps {
  userLocation: UserLocation | null;
}

// Fix for default marker icon issue with Webpack
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png',
  shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/0.7.7/images/marker-shadow.png',
});

// Create a custom red icon for the user's location
const redIcon = new L.Icon({
    iconUrl: 'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-red.png',
    shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/0.7.7/images/marker-shadow.png',
    iconSize: [25, 41],
    iconAnchor: [12, 41],
    popupAnchor: [1, -34],
    shadowSize: [41, 41]
});

const MapDisplay: React.FC<MapDisplayProps> = ({ userLocation }) => {
  const mapRef = useRef<L.Map | null>(null);
  const markerRef = useRef<L.Marker | null>(null);
  const [isFollowingUser, setIsFollowingUser] = useState(true);

  useEffect(() => {
    if (userLocation && !mapRef.current) {
      const initialCoords: L.LatLngExpression = [userLocation.latitude, userLocation.longitude];
      mapRef.current = L.map('mapid').setView(initialCoords, 17);

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
      }).addTo(mapRef.current);

      markerRef.current = L.marker(initialCoords, { icon: redIcon }).addTo(mapRef.current!);

      // マップドラッグ開始時に追従を解除
      mapRef.current.on('dragstart', () => {
        setIsFollowingUser(false);
      });

    } else if (userLocation && mapRef.current && markerRef.current) {
      const newCoords: L.LatLngExpression = [userLocation.latitude, userLocation.longitude];
      markerRef.current.setLatLng(newCoords);
      if (isFollowingUser) {
        mapRef.current.panTo(newCoords);
      }
    }

    // isFollowingUser が true になったときにマップをユーザー位置に移動
    // (ボタンクリック時など)

    return () => {
      // Cleanup map instance on component unmount if this component exclusively owns the map
      // However, in the original code, map cleanup was tied to the main component's lifecycle.
      // If LocationQuiz still controls the overall map lifecycle (e.g. due to watchPosition),
      // this cleanup might need adjustment or be handled in LocationQuiz.
      // For now, assuming MapDisplay manages its own map instance based on its props.
    };
  }, [userLocation]); // isFollowingUser を依存配列から削除し、手動で制御

  const handleFollowUser = () => {
    setIsFollowingUser(true);
    if (userLocation && mapRef.current) {
      const userCoords: L.LatLngExpression = [userLocation.latitude, userLocation.longitude];
      mapRef.current.panTo(userCoords);
      mapRef.current.setZoom(17); // ズームレベルもリセットする（任意）
    }
  };

  return (
    <Box sx={{ position: 'relative', width: '100%', mt: 4 }}>
      <Paper elevation={3} sx={{ height: { xs: '250px', sm: '300px' }, width: '100%', overflow: 'hidden', borderRadius: 2 }}>
        <div id="mapid" style={{ height: '100%', width: '100%' }}></div>
      </Paper>
      {!isFollowingUser && (
        <Fab
          color="primary"
          aria-label="center map on user"
          onClick={handleFollowUser}
          sx={{ position: 'absolute', bottom: 16, right: 16, zIndex: 1000 }} // zIndexでマップの上に表示
        >
          <MyLocationIcon />
        </Fab>
      )}
    </Box>
  );
};

export default MapDisplay;