import React from 'react';
import Typography from '@mui/material/Typography';
import Paper from '@mui/material/Paper';
import Box from '@mui/material/Box';
import { QuizQuestion, QuizData, allQuizzes } from '../quizData'; // Import necessary types and data
import { locations } from '../locationsData'; // Import locations data

interface CompletedQuizzesListProps {
  answeredQuestionIds: number[];
  difficultyLevel: 'elementary' | 'junior_high' | 'high_school';
}

const getLocationNameById = (locationId: number): string => {
    const location = locations.find(loc => loc.id === locationId);
    return location ? location.name : '不明な場所';
};

const CompletedQuizzesList: React.FC<CompletedQuizzesListProps> = ({ answeredQuestionIds, difficultyLevel }) => {
  return (
    <Paper elevation={1} sx={{ p: { xs: 2, sm: 3 }, mt: 4, mb: 1.5 }}>
      <Typography variant="h6" component="h2" gutterBottom>
        クリアした謎解き ({difficultyLevel === 'elementary' ? '小学生' : difficultyLevel === 'junior_high' ? '中学生' : '高校生'})
      </Typography>
      <Box component="ul" sx={{ pl: 2, mt: 1, listStyleType: 'disc' }}>
        {answeredQuestionIds.map(questionId => {
          let answeredQuestion: QuizQuestion | undefined;
          for (const diff of Object.keys(allQuizzes) as Array<keyof QuizData>) {
            answeredQuestion = allQuizzes[diff].find(q => q.id === questionId);
            if (answeredQuestion) break;
          }
          return answeredQuestion && answeredQuestion.difficulty === difficultyLevel ? (
            <Typography component="li" key={answeredQuestion.id} sx={{ mb: 0.5 }}>
              {getLocationNameById(answeredQuestion.locationId)} - クリア！
            </Typography>
          ) : null;
        })}
      </Box>
    </Paper>
  );
};

export default CompletedQuizzesList;