import React from 'react';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import TextField from '@mui/material/TextField';
import Paper from '@mui/material/Paper';
import Stack from '@mui/material/Stack';
import Alert from '@mui/material/Alert';
import { QuizQuestion } from '../quizData'; // Assuming QuizQuestion is exported from quizData
import { locations } from '../locationsData'; // Import locations data

interface QuizInterfaceProps {
  currentQuestion: QuizQuestion;
  userAnswer: string;
  onUserAnswerChange: (answer: string) => void;
  onSubmitAnswer: () => void;
  feedback: string;
}

const getLocationNameById = (locationId: number): string => {
    const location = locations.find(loc => loc.id === locationId);
    return location ? location.name : '不明な場所';
};

const QuizInterface: React.FC<QuizInterfaceProps> = ({
  currentQuestion,
  userAnswer,
  onUserAnswerChange,
  onSubmitAnswer,
  feedback,
}) => {
  return (
    <Paper elevation={3} sx={{ p: { xs: 2, sm: 3 }, mt: 2, backgroundColor: 'secondary.light' }}>
      <Typography variant="body1" gutterBottom sx={{ color: 'secondary.contrastText' }}>
        {getLocationNameById(currentQuestion.locationId)} での謎解き:
      </Typography>
      <Stack spacing={2} sx={{ mt: 2 }}>
        <Typography sx={{ fontWeight: 'medium', color: 'secondary.contrastText' }}>{currentQuestion.question}</Typography>
        <TextField
          fullWidth
          label="回答を入力"
          variant="filled"
          value={userAnswer}
          onChange={(e) => onUserAnswerChange(e.target.value)}
          size="small"
          sx={{ backgroundColor: 'white', borderRadius: 1 }}
        />
        <Button onClick={onSubmitAnswer} variant="contained" color="primary" size="large">
          回答する
        </Button>
        {feedback && (
          <Alert severity={feedback.includes('正解') ? 'success' : 'error'} sx={{ mt: 1 }}>
            {feedback}
          </Alert>
        )}
      </Stack>
    </Paper>
  );
};

export default QuizInterface;