import React, { useState, useEffect, useRef } from 'react'; // Import useRef for map container

// Material UIコンポーネントのインポート
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import Container from '@mui/material/Container';
import Box from '@mui/material/Box';
import Paper from '@mui/material/Paper';
import Stack from '@mui/material/Stack';
import Alert from '@mui/material/Alert';
import CircularProgress from '@mui/material/CircularProgress';

// Import data from separate files
import { locations } from './locationsData';
import { allQuizzes, QuizQuestion, QuizData } from './quizData'; // QuizData をインポート

// Import new components
import DifficultySelector from './components/DifficultySelector';
import MapDisplay from './components/MapDisplay';
import NextObjectiveDisplay from './components/NextObjectiveDisplay';
import StartQuizButton from './components/StartQuizButton';
import QuizInterface from './components/QuizInterface';
import CompletedQuizzesList from './components/CompletedQuizzesList';
import GameStatusDisplay from './components/GameStatusDisplay';



// Define the structure for user's location
interface UserLocation {
  latitude: number;
  longitude: number;
}

// Haversine formula to calculate distance between two points on the Earth (in meters)
const haversineDistance = (coords1: UserLocation, coords2: { latitude: number; longitude: number }): number => {
  const toRad = (value: number) => (value * Math.PI) / 180;

  const R = 6371e3; // Earth's radius in meters
  const dLat = toRad(coords2.latitude - coords1.latitude);
  const dLon = toRad(coords2.longitude - coords1.longitude);
  const lat1 = toRad(coords1.latitude);
  const lat2 = toRad(coords2.latitude);

  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  const distance = R * c; // Distance in meters
  return distance;
};


// Define the proximity radius in meters
const PROXIMITY_RADIUS = 20; // Proximity radius set to 20 meters

// Local Storage Keys
const ANSWERED_QUESTION_IDS_STORAGE_KEY = 'locationQuizAnsweredQuestionIds';
const DIFFICULTY_STORAGE_KEY = 'locationQuizDifficulty';

const LocationQuiz: React.FC = () => {
  const [userLocation, setUserLocation] = useState<UserLocation | null>(null);
  const [quizActive, setQuizActive] = useState<boolean>(false);
  const [userAnswer, setUserAnswer] = useState<string>('');
  const [feedback, setFeedback] = useState<string>('');
  const [answeredQuestionIds, setAnsweredQuestionIds] = useState<number[]>([]);
  const [difficultyLevel, setDifficultyLevel] = useState<'elementary' | 'junior_high' | 'high_school' | null>(null);
  const [currentQuestion, setCurrentQuestion] = useState<QuizQuestion | null>(null); // The currently displayed question
  const [isGameCompleted, setIsGameCompleted] = useState<boolean>(false); // New state for game completion
  const [nextObjectiveLocationName, setNextObjectiveLocationName] = useState<string | null>(null); // New state for next objective location name
  const [nextLocationHint, setNextLocationHint] = useState<string | null>(null); // New state for the hint for the next location
  const [distanceToNextObjective, setDistanceToNextObjective] = useState<number | null>(null); // New state for distance to next objective
  const [soundPlayedForQuestionId, setSoundPlayedForQuestionId] = useState<number | null>(null); // Track if sound played for current question ID



  const audioRef = useRef<HTMLAudioElement | null>(null); // Ref for the audio element
  // Load state from Local Storage on component mount
  useEffect(() => {
    const savedAnsweredQuestionIds = localStorage.getItem(ANSWERED_QUESTION_IDS_STORAGE_KEY);
    const loadedAnsweredIds = savedAnsweredQuestionIds ? JSON.parse(savedAnsweredQuestionIds) : [];
    setAnsweredQuestionIds(loadedAnsweredIds);

    const savedDifficulty = localStorage.getItem(DIFFICULTY_STORAGE_KEY) as 'elementary' | 'junior_high' | 'high_school' | null;
    if (savedDifficulty) {
      setDifficultyLevel(savedDifficulty);
      const quizzesForDifficulty = allQuizzes[savedDifficulty];
      const allAnswered = quizzesForDifficulty.every(q => loadedAnsweredIds.includes(q.id));

      if (allAnswered) {
          setIsGameCompleted(true);
      } else {
          setIsGameCompleted(false);
          // On load, if not completed, find the first unanswered quiz and set hint for its location
          const sortedQuizzes = [...quizzesForDifficulty].sort((a, b) => a.id - b.id);
          const firstUnansweredQuiz = sortedQuizzes.find(q => !loadedAnsweredIds.includes(q.id));

          if (firstUnansweredQuiz) {
              const firstUnansweredLocation = locations.find(loc => loc.id === firstUnansweredQuiz.locationId);
              if (firstUnansweredLocation) { // Use location's hint or fallback
                   setNextLocationHint(firstUnansweredLocation.hint || `${firstUnansweredLocation.name} へ`);
                   setNextObjectiveLocationName(firstUnansweredLocation.name);
              } else {
                   setNextLocationHint('次の場所が見つかりません。'); // Fallback
                   setNextObjectiveLocationName('不明な場所');
              }
              setCurrentQuestion(null); // Clear current question until user is near the location
          } else {
              // Should not happen if not completed and no unanswered quiz is found
              setNextLocationHint(null);
              setNextObjectiveLocationName(null);
          }
      }
    }

  }, []); // Empty dependency array means this runs only once on mount

  // Save state to Local Storage whenever answeredQuestionIds or difficultyLevel changes
  useEffect(() => {
    localStorage.setItem(ANSWERED_QUESTION_IDS_STORAGE_KEY, JSON.stringify(answeredQuestionIds));
  }, [answeredQuestionIds]);

  useEffect(() => {
     if (difficultyLevel) {
        localStorage.setItem(DIFFICULTY_STORAGE_KEY, difficultyLevel);
     } else {
        localStorage.removeItem(DIFFICULTY_STORAGE_KEY);
     }
  }, [difficultyLevel]);

  // Update available quizzes and game completion status when difficulty changes or questions are answered
  useEffect(() => {
      if (difficultyLevel) {
          const quizzesForDifficulty = allQuizzes[difficultyLevel];
          // Filter out questions that have already been answered
          const allAnsweredForDifficulty = quizzesForDifficulty.every(q => answeredQuestionIds.includes(q.id));

          // If all quizzes for the current difficulty are now answered, mark game as completed
          if (allAnsweredForDifficulty && !isGameCompleted) {
              setIsGameCompleted(true);
          }
      }
  }, [difficultyLevel, answeredQuestionIds, isGameCompleted]); // Added isGameCompleted dependency


  // Effect to get and watch user's location and initialize/update map
  useEffect(() => {
    if (!navigator.geolocation) {
      setFeedback('Geolocation is not supported by your browser.');
      return;
    }

    const watchId = navigator.geolocation.watchPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        const newUserLocation = { latitude, longitude };
        setUserLocation(newUserLocation);

        // Map display and updates are now handled by MapDisplay component
      },
      (error) => {
        console.error('Error getting location:', error);
        setFeedback(`Error getting location: ${error.message}`);
      },
      {
        enableHighAccuracy: true,
        timeout: 5000,
        maximumAge: 0,
      }
    );

    // Clean up the watcher when the component unmounts
    return () => {
      navigator.geolocation.clearWatch(watchId);
    };
  }, []); // Empty dependency array means this runs only once on mount

  // Effect to check for nearby quiz locations or make final question available
  useEffect(() => {
    if (userLocation && difficultyLevel && !isGameCompleted) {
      const quizzesForDifficulty = allQuizzes[difficultyLevel];
      const sortedQuizzes = [...quizzesForDifficulty].sort((a, b) => a.id - b.id);

      // Find the first unanswered quiz in the sequence
      const nextQuiz = sortedQuizzes.find(q => !answeredQuestionIds.includes(q.id));

      if (nextQuiz) {
        const nextLocation = locations.find(loc => loc.id === nextQuiz.locationId);

        if (nextLocation) {
          setNextObjectiveLocationName(nextLocation.name); // Set the next objective location name
          setNextLocationHint(nextLocation.hint || `${nextLocation.name} へ`); // Set the hint for the next location using location's hint
          const distance = haversineDistance(userLocation, nextLocation);
          setDistanceToNextObjective(distance); // Set the distance

          // 最終問題かどうかの判定
          const isFinalQuestion = nextQuiz.id === sortedQuizzes[sortedQuizzes.length - 1].id;
          const sixQuestionsAnswered = answeredQuestionIds.length === 6;

          // クイズを表示する条件
          // 最終問題かつ6問回答済み、または通常のクイズで距離が近い場合
          if ((isFinalQuestion && sixQuestionsAnswered) || distance <= PROXIMITY_RADIUS) {
            setCurrentQuestion(nextQuiz);
          } else {
            // 場所が近くない（かつ最終問題の条件も満たさない）
            setCurrentQuestion(null);
            setQuizActive(false);
          }
        } else {
             // Should not happen if locations data is correct, but handle defensively
             setCurrentQuestion(null);
             setQuizActive(false);
             setNextObjectiveLocationName('不明な場所'); // Indicate unknown location
             setNextLocationHint('次の場所が見つかりません。'); // Fallback hint
             setDistanceToNextObjective(null); // Clear distance if location is unknown
             console.error(`Location not found for quiz ID ${nextQuiz.id}`);
        }
      } else {
        // No unanswered quizzes found for this difficulty (game completed)
        setCurrentQuestion(null);
        setQuizActive(false);
        setNextObjectiveLocationName(null); // Clear objective if completed
        setNextLocationHint(null); // Clear hint if game is completed
        setDistanceToNextObjective(null); // Clear distance if game is completed
        // isGameCompleted is set by the availableQuizzes useEffect
      }
    } else if (userLocation && !difficultyLevel) {
        // If location is available but difficulty is not selected, clear states
        setQuizActive(false);
        setFeedback('');
        setUserAnswer('');
        setCurrentQuestion(null);
        setNextObjectiveLocationName(null);
        setNextLocationHint(null);
        setDistanceToNextObjective(null);
    } else if (isGameCompleted) {
        // If game is completed, clear states related to active quiz/location
        setQuizActive(false);
        setCurrentQuestion(null);
        setNextObjectiveLocationName(null);
        setNextLocationHint(null);
        setDistanceToNextObjective(null);
    }
  }, [userLocation, answeredQuestionIds, difficultyLevel, isGameCompleted, allQuizzes, locations]); // Depend on these states

  // Effect to play sound when "Start Quiz" button appears for a new question
  useEffect(() => {
    const shouldShowStartQuizButton = currentQuestion && !isGameCompleted && !quizActive;

    if (shouldShowStartQuizButton) {
      if (currentQuestion.id !== soundPlayedForQuestionId) {
        // Play sound if it's a new question or sound hasn't been played for this button instance
        if (audioRef.current) {
          audioRef.current.play().catch(error => {
            // Autoplay policies might prevent playing without user interaction.
            // Log error, but don't break the app.
            console.error("Audio play failed (autoplay policy might be in effect):", error);
          });
        }
        setSoundPlayedForQuestionId(currentQuestion.id); // Mark sound as played for this question ID
      }
    }
    // No explicit reset of soundPlayedForQuestionId is needed here;
    // it will naturally be different when a new currentQuestion.id arrives.
  }, [currentQuestion, isGameCompleted, quizActive, soundPlayedForQuestionId]);

  // Handle difficulty selection
  const handleDifficultySelect = (difficulty: 'elementary' | 'junior_high' | 'high_school') => {
    setDifficultyLevel(difficulty);
    // When difficulty changes, check if already completed for this difficulty
    const quizzesForDifficulty = allQuizzes[difficulty];
    const allAnswered = quizzesForDifficulty.every(q => answeredQuestionIds.includes(q.id));
    setIsGameCompleted(allAnswered); // Set completion state based on loaded data

    if (allAnswered) {
         // Game is completed for this difficulty
         setNextLocationHint('ゲームクリアです！おめでとうございます！'); // Set final game clear hint
         setNextObjectiveLocationName(null); // Clear objective name
         setDistanceToNextObjective(null); // Clear distance
    } else {
        // On difficulty select, if not completed, find the first unanswered quiz and set hint for its location
        const sortedQuizzes = [...quizzesForDifficulty].sort((a, b) => a.id - b.id);
        const firstUnansweredQuiz = sortedQuizzes.find(q => !answeredQuestionIds.includes(q.id));

        if (firstUnansweredQuiz) {
             const firstUnansweredLocation = locations.find(loc => loc.id === firstUnansweredQuiz.locationId);
             if (firstUnansweredLocation) {
                  setNextLocationHint(firstUnansweredLocation.hint || `${firstUnansweredLocation.name} へ`); // Use location's hint or fallback
                  setNextObjectiveLocationName(firstUnansweredLocation.name);
                  // We don't have userLocation here yet, so distance will be calculated in the location effect
                  setDistanceToNextObjective(null);
             } else {
                  setNextLocationHint('次の場所が見つかりません。'); // Fallback
                  setNextObjectiveLocationName('不明な場所');
                  setDistanceToNextObjective(null);
             }
             setCurrentQuestion(null); // Clear current question if not at a location yet
        } else {
            // Should not happen if not completed and no unanswered quiz is found
            setNextLocationHint(null);
            setNextObjectiveLocationName(null);
            setDistanceToNextObjective(null);
        }
    }
    setFeedback(''); // Clear feedback
    setQuizActive(false); // Hide quiz UI
    setUserAnswer(''); // Clear answer
  };


  // Handle the "Start Quiz" button click
  const handleStartQuiz = () => {
    if (currentQuestion) { // Start quiz if a current question is set
      setQuizActive(true);
      setFeedback('');
      setUserAnswer('');
    }
  };

  // Handle the answer submission
  const handleSubmitAnswer = () => {
    if (currentQuestion && difficultyLevel && userLocation) { // Added difficultyLevel and userLocation check
      // For the final question, any answer is accepted (as per example data)
      const sortedQuizzes = [...allQuizzes[difficultyLevel]].sort((a, b) => a.id - b.id); // Create copy and sort
      const isCurrentQuestionFinal = currentQuestion.id === sortedQuizzes[sortedQuizzes.length - 1].id;

      if (isCurrentQuestionFinal || (userAnswer.trim().toLowerCase() === currentQuestion.answer.toLowerCase())) {
        if (isCurrentQuestionFinal) {
          setFeedback('すべての謎を解き明かした！ゲームクリア！');
        } else {
          setFeedback('正解！！');
        }
        const newAnsweredQuestionIds = [...answeredQuestionIds, currentQuestion.id];
        setAnsweredQuestionIds(newAnsweredQuestionIds); // Mark this specific question as answered
        setQuizActive(false); // Hide the quiz after answering
        setUserAnswer(''); // Clear the answer input

        // Find the next quiz in the sequence for the current difficulty
        const nextQuiz = sortedQuizzes.find(q => !newAnsweredQuestionIds.includes(q.id));


        if (nextQuiz) { // If there is a next quiz
             const nextLocation = locations.find(loc => loc.id === nextQuiz.locationId);
             if (nextLocation) {
                  setNextLocationHint(nextLocation.hint || `${nextLocation.name} へ`); // Use location's hint or fallback
                  setNextObjectiveLocationName(nextLocation.name);
                  // Distance will be calculated in the location effect when userLocation updates
                  setDistanceToNextObjective(null);
             } else {
                  setNextLocationHint('次の場所が見つかりません。'); // Fallback
                  setNextObjectiveLocationName('不明な場所');
                  setDistanceToNextObjective(null);
             }
             setCurrentQuestion(null); // Clear current question until user is near the next location
             setIsGameCompleted(false); // Ensure game is not marked completed if there's a next quiz
        } else { 
             // This was the last quiz (game completed for this difficulty)
             // The feedback "すべての謎を解き明かした！ゲームクリア！" is already set above
             // So, just update the game state and clear objective hints
             setNextLocationHint('すべてのポイントをクリアしました！ゲームクリアです！'); // Set final game clear hint
             setIsGameCompleted(true); // Mark game as completed
             setNextObjectiveLocationName(null); // Clear objective name after answering
             setCurrentQuestion(null); // Clear current question
             setDistanceToNextObjective(null); // Clear distance if game is completed
        }

      } else {
        setFeedback('ちがうよ！もう一度トライ！');
      }
    }
  };

    // Function to reset the game
    const resetGame = () => {
        localStorage.clear(); // Clear all local storage for the game
        window.location.reload(); // Reload the page to reset state
    };

    // Handle "Next Destination" button click
    const handleNextDestination = () => {
        setFeedback(''); // Clear feedback to hide the button and show next objective
    };


  return (
    <Container maxWidth="md" sx={{ py: 4 }}>
      {/* Hidden audio element for the sound effect */}
      {/* 注意: publicフォルダに dingdong.mp3 という名前の効果音ファイルを配置してください */}
      <audio ref={audioRef} src="/dingdong.mp3" preload="auto" style={{ display: 'none' }} />

      {/* タイトル装飾 */}
      <Box sx={{ display: 'flex', justifyContent: 'center', mb: 4 }}>
        <Paper elevation={3} sx={{ py: 1.5, px: { xs: 2, sm: 4 }, backgroundColor: 'primary.main', display: 'inline-block', borderRadius: 2 }}>
          <Typography variant="h4" component="h1" align="center" fontWeight="bold" sx={{ color: 'primary.contrastText' }}>
            謎解きゲーム
          </Typography>
        </Paper>
      </Box>
      
      {!userLocation && (
        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', flexDirection: 'column', my: 4 }}>
          <CircularProgress />
          <Typography sx={{ mt: 2 }}>位置情報を取得中です...</Typography>
        </Box>
      )}

      {userLocation && (
        <>
          <Stack spacing={3}>
          {!difficultyLevel && <DifficultySelector onSelectDifficulty={handleDifficultySelect} />}

          {/* Display the next objective location name, hint, and distance, or game completed status */}
          {difficultyLevel && (nextObjectiveLocationName || nextLocationHint || distanceToNextObjective !== null || isGameCompleted) && (
              <NextObjectiveDisplay
                nextLocationHint={nextLocationHint}
                distanceToNextObjective={distanceToNextObjective}
                isGameCompleted={isGameCompleted}
              />
          )}

          {/* "Next Destination" button after correct answer, but not for the final question */}
          {feedback === '正解！！' && !quizActive && !isGameCompleted && (
            <Box sx={{ textAlign: 'center', mt: 2 }}>
              <Button
                variant="contained"
                color="success"
                size="large"
                onClick={handleNextDestination}
              >
                次の目的地へ
              </Button>
            </Box>
          )}


          {/* Show "Start Quiz" button or Quiz UI if a question is available and game is not completed */}
          {currentQuestion && !isGameCompleted ? ( // Check currentQuestion instead of nearbyLocation for showing quiz UI
             !quizActive ? (
                <StartQuizButton currentQuestion={currentQuestion} onStartQuiz={handleStartQuiz} />
             ) : (
                <QuizInterface
                  currentQuestion={currentQuestion}
                  userAnswer={userAnswer}
                  onUserAnswerChange={setUserAnswer}
                  onSubmitAnswer={handleSubmitAnswer}
                  feedback={feedback}
                />
             )
          ) : (
            // Show message when no relevant point is nearby and not game over,
            // AND there are still unanswered quizzes for the selected difficulty.
            userLocation && difficultyLevel && !isGameCompleted &&
            allQuizzes[difficultyLevel].some(q => !answeredQuestionIds.includes(q.id)) &&
            !currentQuestion && ( // Only show this message if no current question is set
                 <Typography sx={{ mt: 2, textAlign: 'center', p:2 }} component={Paper} elevation={1}>
                     謎解きポイントに近づいて！！
                 </Typography>
            )
          )}

          {/* Map Container - Moved to the bottom and made smaller */}
          <MapDisplay userLocation={userLocation} />
          </Stack>

          {/* 難易度表示 (リセットボタンの少し上) */}
          {difficultyLevel && (answeredQuestionIds.length > 0) && (
            <CompletedQuizzesList
                answeredQuestionIds={answeredQuestionIds}
                difficultyLevel={difficultyLevel}
            />
          )}

          <GameStatusDisplay difficultyLevel={difficultyLevel} onResetGame={resetGame} />
        </>
      )}
      {feedback && !userLocation && <Alert severity="error" sx={{ mt: 2 }}>{feedback}</Alert>}
    </Container>
  );
};

export default LocationQuiz;
